settingsPage=async()=>S.user.role==='owner'?originalSettings():head('Settings & imports','Pricing imports and security actions are controlled by management.')+xnote('You have access to all operational modules. User-role changes, secrets, refunds and payroll release remain management approval actions.','teal')+`<div class="row wrap">${xbtn('go-policies','View operating rules')}${xbtn('go-connections','View connections')}${xbtn('go-rates','View daily rates')}</div>`;
const originalBootstrap=bootstrap;
bootstrap=async function(){if(location.hash.startsWith('#reset=')){const token=location.hash.slice(7);history.replaceState(null,'',location.pathname);root.innerHTML='<div class="startup">Reset your CrownOps password</div>';return xf('reset','Reset password',field('password','New password','','password','minlength="12" required'),'Reset password',{token});}return originalBootstrap();};
